  ["untracked-scoped-count", "\"$HORIZON_GIT\" status --porcelain=v1 --untracked-files=all | awk '$1==\"??\" && substr($0,4) ~ /^MainProjects\\/(Algebraic-Jacobian-Challenge-Rebuild|Algebraic-Jacobian-Challenge)\\// {n++} END{print n+0}'"]
];
const rs = await Promise.all(specs.map(async ([name,cmd]) => {
  const r=await tools.exec_command({cmd,workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:12000});
