rs.forEach(text);

const cmds = [
  ["status-counts", "set -o pipefail; \"$HORIZON_GIT\" status --porcelain=v1 --untracked-files=all | awk 'BEGIN{all=0;staged=0;unstaged=0;untracked=0;shared=0;scoped=0;scoped_rebuild=0;scoped_challenge=0;scoped_source=0;scoped_hgraph=0;scoped_other=0;shared_hgraph=0;shared_inbox=0;shared_refs=0;shared_other=0} {all++; x=substr($0,1,2); p=substr($0,4); isScope=(p ~ /^MainProjects\\/(Algebraic-Jacobian-Challenge-Rebuild|Algebraic-Jacobian-Challenge)\\//); if (x==\"??\") untracked++; else {if (substr(x,1,1)!=\" \") staged++; if (substr(x,2,1)!=\" \") unstaged++} if(isScope){scoped++; if(p ~ /^MainProjects\\/Algebraic-Jacobian-Challenge-Rebuild\\//) scoped_rebuild++; else scoped_challenge++; if(p ~ /\\.lean$/ || p ~ /\\.md$/ && p !~ /\\/hgraph\\//) scoped_source++; if(p ~ /\\/hgraph\\//) scoped_hgraph++; if(p !~ /\\.lean$/ && p !~ /\\/hgraph\\//) scoped_other++} else {shared++; if(p ~ /^\\.archon-horizon\\/inbox\\//) shared_inbox++; else if(p ~ /^\\.archon-horizon\\/.*hgraph|\\/hgraph\\//) shared_hgraph++; else if(p ~ /^references\\//) shared_refs++; else shared_other++}} END{printf \"all=%d staged=%d unstaged=%d untracked=%d scoped=%d (rebuild=%d challenge=%d source=%d hgraph=%d other=%d) shared=%d (inbox=%d hgraph=%d refs=%d other=%d)\\n\",all,staged,unstaged,untracked,scoped,scoped_rebuild,scoped_challenge,scoped_source,scoped_hgraph,scoped_other,shared,shared_inbox,shared_hgraph,shared_refs,shared_other}'"],
  ["scoped-names", "\"$HORIZON_GIT\" status --porcelain=v1 --untracked-files=all | awk 'substr($0,4) ~ /^MainProjects\\/(Algebraic-Jacobian-Challenge-Rebuild|Algebraic-Jacobian-Challenge)\\// {p=substr($0,4); if (p ~ /\\.lean$/ || p !~ /\\/hgraph\\//) print}' | head -100"],
  ["scoped-lean-diff", "\"$HORIZON_GIT\" diff --name-status -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild MainProjects/Algebraic-Jacobian-Challenge -- '*.lean'"],
  ["scoped-blueprint-diff", "\"$HORIZON_GIT\" diff --name-status -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild MainProjects/Algebraic-Jacobian-Challenge -- '*.tex' '*.yaml' '*.json'"],
  ["scoped-hgraph-count", "\"$HORIZON_GIT\" status --porcelain=v1 --untracked-files=all | awk 'substr($0,4) ~ /^MainProjects\\/(Algebraic-Jacobian-Challenge-Rebuild|Algebraic-Jacobian-Challenge)\\/hgraph\\// {n++; if(substr($0,1,2)==\"??\") u++; else m++} END{printf \"scoped hgraph entries: total=%d modified=%d untracked=%d\\n\",n,m,u}'"],
  ["shared-counts", "\"$HORIZON_GIT\" status --porcelain=v1 --untracked-files=all | awk 'BEGIN{n=0} {p=substr($0,4); if(p !~ /^MainProjects\\/(Algebraic-Jacobian-Challenge-Rebuild|Algebraic-Jacobian-Challenge)\\//){n++; if(p ~ /^\\.archon-horizon\\/inbox\\//) i++; else if(p ~ /^\\.archon-horizon\\/hgraph\\// || p ~ /\\/hgraph\\//) h++; else if(p ~ /^references\\//) r++; else o++}} END{printf \"shared/other entries: total=%d inbox=%d hgraph=%d references=%d other=%d\\n\",n,i,h,r,o}'"],
  ["ledger-head", "\"$HORIZON_GIT\" rev-parse --abbrev-ref HEAD; \"$HORIZON_GIT\" rev-parse HEAD; \"$HORIZON_GIT\" log -1 --format='%h %ad %s' --date=iso-strict"],
  ["recent-ajcr-commits", "\"$HORIZON_GIT\" log -12 --format='%h %ad %(trailers:key=Archon-Session,valueonly) %(trailers:key=Archon-Task,valueonly) %s' --date=iso-strict -- MainProjects/Algebraic-Jacobian-Challenge-Rebuild"],
  ["run-process", "if test -f \"$ARCHON_HORIZON_ROOT/.archon-horizon/runs/$ARCHON_HORIZON_RUN/process.json\"; then jq '{run,pid,started_at,status,task,session}' \"$ARCHON_HORIZON_ROOT/.archon-horizon/runs/$ARCHON_HORIZON_RUN/process.json\"; else echo no-process; fi"]
];
